{
  "source_context": [
    {
      "section": "V1",
      "lyrics": [
        "街明かり華やか",
        "エーテル麻酔の冷たさ",
        "眠れない午前二時",
        "全てが急速に変わる",
        "オイル切れのライター",
        "焼けつくような胃の中",
        "全てがそう嘘なら",
        "本当によかったのにね"
      ]
    },
    {
      "section": "B1",
      "lyrics": [
        "君の首を締める夢を見た",
        "光の溢れる昼下がり",
        "君の細い喉が跳ねるのを",
        "泣き出しそうな眼で見ていた"
      ]
    },
    {
      "section": "C1",
      "lyrics": [
        "核融合炉にさ",
        "飛び込んでみたいと思う",
        "真っ青な光包まれて奇麗",
        "核融合炉にさ",
        "飛び込んでみたらそしたら",
        "すべてが許されるような気がして"
      ]
    },
    {
      "section": "V2",
      "lyrics": [
        "ベランダの向こう側",
        "階段を昇ってゆく音",
        "陰り出した空が",
        "窓ガラスに 部屋に落ちる",
        "拡散する夕暮れ",
        "泣き腫らしたような陽の赤",
        "融けるように少しずつ",
        "少しずつ死んでゆく世界",
        "君の首を締める夢を見た",
        "春風に揺れるカーテン",
        "乾いて切れた唇から",
        "零れる言葉は泡のよう"
      ]
    },
    {
      "section": "C2",
      "lyrics": [
        "核融合炉にさ",
        "飛び込んでみたいと思う",
        "真っ青な光包まれて奇麗",
        "核融合炉にさ",
        "飛び込んでみたらそしたら",
        "すべてが許されるような気がして"
      ]
    },
    {
      "section": "V3",
      "lyrics": [
        "時計の秒針や",
        "テレビの司会者や",
        "そこにいるけど",
        "見えない誰かの",
        "笑い声",
        "飽和して反響する",
        "アレグロ･アジテート",
        "耳鳴りが消えない止まない",
        "アレグロ･アジテート",
        "耳鳴りが消えない止まない"
      ]
    },
    {
      "section": "B2",
      "lyrics": [
        "誰もみんな消えてく夢を見た",
        "真夜中の部屋の広さと静寂が",
        "胸につっかえて",
        "上手に息ができなくなる"
      ]
    },
    {
      "section": "C3",
      "lyrics": [
        "核融合炉にさ",
        "飛び込んでみたらそしたら",
        "きっと眠るように消えていけるんだ",
        "僕のいない朝は",
        "今よりずっと素晴らしくて",
        "全ての歯車が噛み合った",
        "きっとそんな世界だ"
      ]
    }
  ],
  "section": "B1",
  "phrases": [
    {
      "id": "B1-01",
      "ja": "君の首を締める夢を見た",
      "budget": {
        "min": 14,
        "max": 14
      },
      "pattern": null
    },
    {
      "id": "B1-02",
      "ja": "光の溢れる昼下がり",
      "budget": {
        "min": 13,
        "max": 13
      },
      "pattern": null
    },
    {
      "id": "B1-03",
      "ja": "君の細い喉が跳ねるのを",
      "budget": {
        "min": 14,
        "max": 14
      },
      "pattern": null
    },
    {
      "id": "B1-04",
      "ja": "泣き出しそうな眼で見ていた",
      "budget": {
        "min": 12,
        "max": 12
      },
      "pattern": null
    }
  ],
  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "梦见自己 亲手掐住你的脖颈"
        },
        {
          "id": "B1-02",
          "zh": "午后阳光 满溢得刺眼"
        },
        {
          "id": "B1-03",
          "zh": "你纤细的喉咙 微微地颤动"
        },
        {
          "id": "B1-04",
          "zh": "用快要哭出来的眼睛望着我"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "我梦见了自己用力紧紧勒住了他"
        },
        {
          "id": "B1-02",
          "zh": "在那阳光灿烂满溢的午后时分"
        },
        {
          "id": "B1-03",
          "zh": "你那条纤细喉咙不停跳动的模样"
        },
        {
          "id": "B1-04",
          "zh": "用快要哭出来的眼神望着他"
        }
      ]
    }
  ]
}

